import re, html, sys, pandas as pd
path=sys.argv[1]; xml=open(path,encoding='utf8').read(); n0=xml.count('<w:p ')
def esc(s): return html.escape(s, quote=False).replace("'", "&apos;")
RPR='<w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:cs="Times New Roman"/><w:sz w:val="24"/><w:szCs w:val="24"/></w:rPr>'
RPRB=RPR.replace('<w:sz w:val="24"/>','<w:b/><w:sz w:val="24"/>')
PPR='<w:pPr><w:spacing w:after="120" w:line="360" w:lineRule="auto"/><w:jc w:val="both"/>'+RPR+'</w:pPr>'
def para(text, lead=None):
    r=(f'<w:r>{RPRB}<w:t xml:space="preserve">{esc(lead)}</w:t></w:r>' if lead else '')+f'<w:r>{RPR}<w:t xml:space="preserve">{esc(text)}</w:t></w:r>'
    return f'<w:p w:rsidR="007372E6" w:rsidRPr="00A97429" w:rsidRDefault="003C27D6" w:rsidP="00A97429">{PPR}{r}</w:p>'
def heading2(text):
    R='<w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:cs="Times New Roman"/><w:sz w:val="28"/><w:szCs w:val="28"/></w:rPr>'
    return f'<w:p w:rsidR="007372E6" w:rsidRPr="00A97429" w:rsidRDefault="003C27D6" w:rsidP="00A97429"><w:pPr><w:pStyle w:val="Heading2"/><w:spacing w:line="360" w:lineRule="auto"/>{R}</w:pPr><w:r>{R}<w:t>{esc(text)}</w:t></w:r></w:p>'
def table(rows,widths,sz=16):
    B='<w:tblBorders>'+''.join(f'<w:{s} w:val="single" w:sz="4" w:space="0" w:color="auto"/>' for s in ['top','left','bottom','right','insideH','insideV'])+'</w:tblBorders>'
    t=f'<w:tbl><w:tblPr><w:tblW w:w="{sum(widths)}" w:type="dxa"/>{B}</w:tblPr><w:tblGrid>'+''.join(f'<w:gridCol w:w="{w}"/>' for w in widths)+'</w:tblGrid>'
    for i,row in enumerate(rows):
        t+='<w:tr>'
        for j,c in enumerate(row):
            rp='<w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:cs="Times New Roman"/>'+('<w:b/>' if i==0 or j==0 else '')+f'<w:sz w:val="{sz}"/><w:szCs w:val="{sz}"/></w:rPr>'
            t+=f'<w:tc><w:tcPr><w:tcW w:w="{widths[j]}" w:type="dxa"/></w:tcPr><w:p><w:pPr><w:spacing w:after="0" w:line="240" w:lineRule="auto"/><w:jc w:val="{"left" if j==0 else "center"}"/></w:pPr><w:r>{rp}<w:t xml:space="preserve">{esc(str(c))}</w:t></w:r></w:p></w:tc>'
        t+='</w:tr>'
    return t+'</w:tbl>'

def table2(rows,widths,groups,sz=16):
    """groups: lista di (label, n_colonne) per la riga di intestazione superiore; la prima colonna è esclusa"""
    B='<w:tblBorders>'+''.join(f'<w:{s} w:val="single" w:sz="4" w:space="0" w:color="auto"/>' for s in ['top','left','bottom','right','insideH','insideV'])+'</w:tblBorders>'
    t=f'<w:tbl><w:tblPr><w:tblW w:w="{sum(widths)}" w:type="dxa"/>{B}</w:tblPr><w:tblGrid>'+''.join(f'<w:gridCol w:w="{w}"/>' for w in widths)+'</w:tblGrid>'
    def cell(text,w,bold,span=1,jc='center'):
        rp='<w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:cs="Times New Roman"/>'+('<w:b/>' if bold else '')+f'<w:sz w:val="{sz}"/><w:szCs w:val="{sz}"/></w:rPr>'
        gs=f'<w:gridSpan w:val="{span}"/>' if span>1 else ''
        return f'<w:tc><w:tcPr><w:tcW w:w="{w}" w:type="dxa"/>{gs}</w:tcPr><w:p><w:pPr><w:spacing w:after="0" w:line="240" w:lineRule="auto"/><w:jc w:val="{jc}"/></w:pPr><w:r>{rp}<w:t xml:space="preserve">{esc(str(text))}</w:t></w:r></w:p></w:tc>'
    t+='<w:tr>'+cell('',widths[0],True,jc='left'); k=1
    for lab,n in groups:
        t+=cell(lab,sum(widths[k:k+n]),True,span=n); k+=n
    t+='</w:tr>'
    for i,row in enumerate(rows):
        t+='<w:tr>'+''.join(cell(c,widths[j],(i==0 or j==0),jc=('left' if j==0 else 'center')) for j,c in enumerate(row))+'</w:tr>'
    return t+'</w:tbl>'

def note(text):
    R=RPR.replace('24','20')
    return f'<w:p w:rsidR="007372E6" w:rsidRPr="00A97429" w:rsidRDefault="003C27D6" w:rsidP="00A97429"><w:pPr><w:spacing w:after="120" w:line="276" w:lineRule="auto"/><w:jc w:val="both"/>{R}</w:pPr><w:r>{R}<w:t xml:space="preserve">{esc(text)}</w:t></w:r></w:p>'
def find(old,count=1):
    for o in (esc(old), html.escape(old,quote=False), old.replace('&','&amp;').replace('&amp;amp;','&amp;'), old):
        if xml.count(o)==count: return o
    raise AssertionError((old[:80], xml.count(esc(old))))
def rep(old,new,count=1):
    global xml
    o=find(old,count); xml=xml.replace(o,esc(new))
def para_bounds(text):
    i=xml.find(find(text)); a=xml.rfind('<w:p ',0,i); b=xml.find('</w:p>',i)+6; return a,b
def set_para(anchor,new,lead=None):
    global xml
    a,b=para_bounds(anchor); p=xml[a:b]
    m=re.search(r'<w:pPr>.*?</w:pPr>',p,flags=re.S); ppr=m.group(0) if m else ''
    mr=re.search(r'<w:r>(<w:rPr>.*?</w:rPr>)?',p,flags=re.S); rpr=(mr.group(1) or RPR) if mr else RPR
    rpr=re.sub(r'<w:b/>|<w:bCs/>|<w:i/>|<w:iCs/>','',rpr); rprb=rpr.replace('<w:rPr>','<w:rPr><w:b/>')
    head=re.match(r'<w:p [^>]*>',p).group(0)
    body=(f'<w:r>{rprb}<w:t xml:space="preserve">{esc(lead)}</w:t></w:r>' if lead else '')+f'<w:r>{rpr}<w:t xml:space="preserve">{esc(new)}</w:t></w:r>'
    xml=xml[:a]+head+ppr+body+'</w:p>'+xml[b:]

# ===================== §6bis ricostruito =====================
rep("6bis. Privatizzazioni, quota salari e quasi-rendite: il test di Modiano-Onado","6bis. Privatizzazioni, rendite e investimenti: il test di Modiano-Onado")
rep("ma NON hanno investito significativamente in innovazione tecnologica e — questa è l'ipotesi che il DiD di §6bis.2-6bis.5 sottopone a verifica e che §6bis.6 riformula — avrebbero compresso i salari della manodopera occupata.",
    "ma NON hanno investito significativamente in innovazione tecnologica: hanno trasformato una rendita pubblica in una rendita privata non reinvestita. È questa, e non la compressione dei salari nei settori ceduti, l'ipotesi che le sezioni seguenti sottopongono a verifica.")
set_para("Nella nostra interpretazione, il conflitto di classe nelle privatizzazioni è esplicito",
    "Nella nostra interpretazione il conflitto di classe nelle privatizzazioni non sta in un effetto diretto sui salari dei settori ceduti: la compressione salariale del 1992-93 è generale, precede le cessioni del 1997-2001 e colpisce tutti i settori, compresi quelli che un disegno controfattuale userebbe come controllo (§5). Sta nel fatto che, in un'economia con lavoro già a basso costo e concorrenza incompleta, il passaggio dal pubblico al privato rafforza una propensione alla rendita già forte: i profitti delle imprese cedute crescono per posizione di mercato e per capitale infrastrutturale ereditato dallo Stato, e non tornano in accumulazione. La firma empirica della tesi non è quindi sulla quota salari, ma sulla coppia profitti-investimenti per branca, che i conti nazionali Eurostat consentono di osservare dal 1995.")
# elimina tutto da "6bis.2 Test empirico: DiD" fino al paragrafo prima di "6bis.6 Riformulazione" (incluso l'heading 6bis.6)
a,_=para_bounds("6bis.2 Test empirico: DiD privatizzazioni su wage share"); _,b=para_bounds("6bis.6 Riformulazione: quasi-rendite non reinvestite, non compressione salariale")
t=pd.read_csv(sys.argv[2])
P=lambda br,per,c: f"{t[(t.branca==br)&(t.periodo==per)][c].iloc[0]:.0f}" if c!='crescita_VA_reale' else f"{t[(t.branca==br)&(t.periodo==per)][c].iloc[0]:+.1f}".replace('.',',')
PER=['1995-2000','2001-07','2008-13','2014-24']
rows=[["Branca (NACE)"]+PER*3]
for br,lab in [('Energia','Energia (D)'),('Telecom','Telecomunicazioni (J61)'),('Finanza','Finanza (K)'),('Trasporti (H)','Trasporti (H)'),('Manifatt.','Manifatturiero (C)'),('Totale','Totale economia')]:
    rows.append([lab]+[P(br,p,'quota_profitti') for p in PER]+[P(br,p,'inv_su_surplus') for p in PER]+[(P(br,p,'crescita_VA_reale') if not pd.isna(t[(t.branca==br)&(t.periodo==p)]['crescita_VA_reale'].iloc[0]) else '—') for p in PER])
new = heading2("6bis.2 Torrini (2005, 2016): la rendita trasferita, non ridotta") \
 + para("Prima di Modiano e Onado, e con gli strumenti della contabilità settoriale, Torrini (2005) aveva già documentato il meccanismo. L'aumento della quota dei profitti italiana negli anni Novanta non è diffuso: si concentra nei tre comparti a maggiore presenza pubblica — energia, trasporti e comunicazioni, finanza — che nel 1989-2001 \"sono gli unici in cui il rendimento del capitale si è accresciuto\" (p. 28), con costo del lavoro cresciuto \"meno che negli altri settori e in misura inferiore all'indice dei prezzi al consumo\" (p. 29) e uno spread fra rendimento e costo d'uso del capitale \"aumentato considerevolmente nel privato al netto manifatturiero\" (p. 26). La spiegazione è istituzionale, non tecnologica: poiché le privatizzazioni \"sono state mosse soprattutto dall'esigenza dello Stato di ridurre il debito, le preoccupazioni per la tutela della concorrenza e per la regolamentazione dei monopoli naturali […] sembrano aver giocato un ruolo di secondo piano\", sicché \"i guadagni di efficienza si sarebbero quindi tradotti principalmente in un ampliamento dei margini piuttosto che in una riduzione dei prezzi\" (p. 29). Le privatizzazioni \"non si siano tradotte in una riduzione del potere di mercato, determinando una redistribuzione delle rendite dai salari ai profitti\" (p. 30); nelle conclusioni: \"hanno accresciuto l'efficienza senza ridurre il potere di mercato delle imprese privatizzate, con conseguente aumento della redditività\" (p. 34). Torrini (2016, p. 20) conferma con dati aggiornati: dal 1995 la quota del lavoro nei settori regolati cala di otto punti, \"consistent with a shift in rents from labour to capital […] and a rise in the required return to capital following privatization and stock market listing\", e si stabilizza dal 2001.") \
 + para("Due precisazioni. L'ordine causale in Torrini è lo stesso del nostro: la moderazione salariale nasce dagli accordi del 1992, \"raggiunti durante una delle recessioni più severe del dopoguerra\" con il debito che impediva allo Stato di sostenere l'occupazione (pp. 27-28), è generale e precede; le privatizzazioni, \"per la loro concentrazione in alcuni settori specifici, possono ampiamente dar conto\" delle differenze settoriali (p. 28). E la misura dell'\"efficienza\" di Torrini è la produttività totale dei fattori, che per le ragioni di §4.2bis non adottiamo: ne tratteniamo i fatti fisici — occupazione privata in calo del 4,6 per cento \"per la prima volta in 30 anni\" (p. 28), costo del lavoro sotto l'inflazione, rapporto capitale/prodotto fermo — non la misura. Soprattutto, Torrini nel 2005 non sostiene che la rendita non venga reinvestita; al contrario, si aspetta che i settori privatizzati godano di \"favorevoli andamenti della redditività relativa, tali da stimolarne l'espansione, sempre che le condizioni istituzionali favoriscano la crescita e l'entrata di nuovi operatori e non permettano il consolidarsi di posizioni di monopolio\" (p. 32). È un'attesa condizionale, formulata a metà del processo. Vent'anni dopo, i conti nazionali per branca permettono di verificarla.") \
 + heading2("6bis.3 Verifica ex post sui conti nazionali per branca, 1995-2024") \
 + para("Usiamo i conti nazionali Eurostat per branca NACE A64 (nama_10_a64 per valore aggiunto e redditi da lavoro, nama_10_a64_p5 per gli investimenti fissi lordi; valori correnti e valore aggiunto in volume), Italia 1995-2024, per le branche privatizzate o quotate negli anni Novanta — energia (D), telecomunicazioni (J61), finanza (K), trasporti (H: per la sottobranca H49 gli investimenti non sono pubblicati) — e per il manifatturiero (C), il settore esposto alla concorrenza internazionale che Torrini usa come termine di confronto, e il totale dell'economia. Tre indicatori, in medie di periodo: la quota dei profitti sul valore aggiunto, (B1G − D1)/B1G; la quota di surplus reinvestita, cioè investimenti fissi lordi su surplus operativo lordo, P51G/(B1G − D1); la crescita media annua del valore aggiunto in volume, che misura l'\"espansione\" attesa da Torrini. I periodi seguono la periodizzazione del paper. Script e dati sono nel repository (privatizzate_surplus.py).") \
 + table2(rows,[1700]+[575]*12,[('Quota dei profitti sul VA (%)',4),('Surplus reinvestito (%)',4),('VA in volume, % annuo',4)]) \
 + note("Tabella 6bis.1 — Settori privatizzati e manifatturiero, Italia 1995-2024: quota dei profitti sul valore aggiunto (%), quota di surplus reinvestita (investimenti fissi lordi in % del surplus operativo lordo), crescita media annua del valore aggiunto in volume (%). Fonte: Eurostat nama_10_a64 (B1G, D1, CP_MEUR e CLV10_MEUR) e nama_10_a64_p5 (P51G, N11G), estrazione del 10 novembre 2026. Per H il valore aggiunto in volume non è calcolato per discontinuità di serie.") \
 + para("La lettura è univoca. Nell'energia la quota dei profitti sale da 60 a 78 per cento e la quota di surplus reinvestita scende da 169 a 73: un settore che nel 1995-2007 investiva più del proprio surplus — il ciclo delle centrali a ciclo combinato, va detto, gonfia il dato iniziale — ne reinveste meno di tre quarti nel 2014-24, mentre il valore aggiunto in volume si contrae per vent'anni. Nella finanza la quota dei profitti sale da 40 a 57 e il surplus reinvestito scende da un quarto a un settimo, con crescita reale che si annulla e poi diventa negativa. Le telecomunicazioni mostrano le due fasi in sequenza: nel 1995-2007 la rendita (quota profitti all'80 per cento, surplus reinvestito da 49 a 32) con una crescita in volume ancora forte, poi, quando la concorrenza arriva davvero, la rendita evapora, il peso del settore sul valore aggiunto totale si dimezza (dall'1,9 allo 0,8 per cento) e il reinvestimento risale su un settore ormai piccolo: gli investimenti in fibra del 2014-24 arrivano quando non c'è più rendita da reinvestire. Nei trasporti la quota dei profitti sale di sette punti e il surplus reinvestito scende di undici.") \
 + para("Il contrasto decisivo è con il manifatturiero. È l'unico comparto in cui la quota dei profitti scende (da 49 a 45) ed è anche l'unico in cui la quota di surplus reinvestita sale, da 39 a 55 per cento: dove i profitti sono guadagnati sotto concorrenza si reinveste di più; dove sono rendita si reinveste di meno. L'aggregato resta fermo intorno al 39 per cento perché i due movimenti si compensano, ed è per questo che la firma nei conti nazionali aggregati (la decomposizione di Kalecki di §4.3, con il rapporto investimento privato/surplus da 0,48 a 0,34) è più debole di quella settoriale. L'attesa di Torrini non si è realizzata: la condizione che egli stesso poneva — che le istituzioni impedissero il consolidarsi di posizioni di monopolio — non si è verificata, come già ammetteva fosse probabile (p. 29), e l'espansione non c'è stata. La tesi di Modiano e Onado, formulata ex post, è quella che i dati confermano. Due cautele: nell'energia la quota dei profitti del 2022-24 è gonfiata dai prezzi dell'energia, e il calo degli investimenti dopo il 2008 è anche la fine del ciclo degli impianti; ma la tendenza regge escludendo il 2022-24 e vale, con la stessa direzione, per finanza e trasporti, dove quei fattori non operano.") \
 + heading2("6bis.4 Perché non un difference-in-differences") \
 + para("In versioni precedenti di questo lavoro la tesi era stata testata con un difference-in-differences sulla quota dei salari delle branche privatizzate contro branche di controllo, prima su dati aggregati e poi sugli stessi dati Eurostat A64. L'esercizio è stato abbandonato per due ragioni, e lo riportiamo per trasparenza. La prima è di identificazione: i dati per branca iniziano nel 1995, la rottura distributiva è del 1992-93 e colpisce tutti i settori, le liberalizzazioni precedono le cessioni formali; i trend pre-trattamento non sono paralleli e gli stimatori divergono (lo stimatore a effetti fissi dava −16,5 punti, quello di Callaway e Sant'Anna (2021), robusto alla tempistica scaglionata, +2,3 punti con intervallo [+0,3; +4,3]), per le ragioni note da Goodman-Bacon (2021) e de Chaisemartin e D'Haultfœuille (2020). La seconda è concettuale e più importante: la quota dei salari di una branca è redditi da lavoro su valore aggiunto, e un valore aggiunto gonfiato dalla rendita la abbassa esattamente come un salario compresso. Il disegno non poteva distinguere le due tesi che intendeva separare. Codice, dati e output restano nel repository (did_callaway_santanna.R) e non sono fra i risultati del paper.") \
 + heading2("6bis.5 Riformulazione: la rendita che si innesta su salari già compressi")
xml=xml[:a]+new+xml[b:]
set_para("Il risultato negativo del DiD spinge a riformulare che cosa la tesi di Modiano-Onado",
    "La tesi di Modiano e Onado, e prima quella di Torrini (2005, 2016), non è che le privatizzazioni abbiano compresso i salari: è che le imprese privatizzate abbiano prodotto profitti di natura di quasi-rendita, per posizione di mercato e per capitale infrastrutturale ereditato dallo Stato, e che questi profitti non siano stati reinvestiti — distribuiti come dividendi, impiegati in acquisizioni e ristrutturazioni finanziarie, o incassati su un capitale che non veniva rinnovato. La quasi-rendita, nel senso marshalliano di rendimento di un fattore fisso, dura qui non un breve periodo ma decenni, perché il capitale ereditato è durevole e nessuno lo rimpiazza: è coerente con i break al ribasso di I/K nel 1992, 2006 e 2015 (§5.5) e con la Tabella 6bis.1. Il meccanismo non è causale nel senso privatizzazione → compressione salariale: è un innesto. La compressione del 1992-93 è generale e precede; su di essa, in un'economia con concorrenza incompleta, le privatizzazioni rafforzano una propensione alla rendita già forte e spingono il capitalismo italiano su una strada di non-sviluppo: profitti senza accumulazione, salari senza produttività. A livello aggregato è ciò con cui la decomposizione di Kalecki di §4.3 è coerente per il 1993-2007: profitti lordi stabili, investimento privato in calo di due punti, residuo C_π − S_w in crescita di oltre cinque punti di PIL con il risparmio netto delle famiglie dimezzato, rapporto investimento privato/surplus da 0,48 a 0,34. In termini teorici, è il caso in cui la distribuzione si sposta a favore dei profitti ma l'investimento non risponde alla quota profitti (Bhaduri e Marglin 1990), per orientamento al valore per l'azionista (Stockhammer 2004): profitti senza accumulazione.")

